<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Ball Physics Playground</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #1a1a2e;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: #e0e0e0;
    overflow: hidden;
  }
  h1 {
    margin-bottom: 20px;
    font-weight: 300;
    letter-spacing: 2px;
    font-size: 1.5em;
    color: #a8dadc;
  }
  #sim {
    border: 2px solid #457b9d;
    border-radius: 8px;
    cursor: crosshair;
    display: block;
    background: #16213e;
    box-shadow: 0 0 30px rgba(69, 123, 157, 0.3);
  }
  .controls {
    margin-top: 20px;
    display: flex;
    gap: 15px;
  }
  button {
    padding: 10px 24px;
    border: none;
    border-radius: 6px;
    font-size: 1em;
    cursor: pointer;
    transition: all 0.2s ease;
    font-weight: 500;
    letter-spacing: 1px;
  }
  #drop {
    background: linear-gradient(135deg, #e94560, #c23152);
    color: white;
  }
  #drop:hover { transform: translateY(-2px); box-shadow: 0 4px 15px rgba(233, 69, 96, 0.4); }
  #play {
    background: linear-gradient(135deg, #0f3460, #16213e);
    color: #a8dadc;
    border: 1px solid #457b9d;
  }
  #play:hover { transform: translateY(-2px); box-shadow: 0 4px 15px rgba(69, 123, 157, 0.4); }
  #clear {
    background: linear-gradient(135deg, #533483, #3b246b);
    color: white;
  }
  #clear:hover { transform: translateY(-2px); box-shadow: 0 4px 15px rgba(83, 52, 131, 0.4); }
  .hint {
    margin-top: 12px;
    font-size: 0.85em;
    color: #6c7a89;
  }
</style>
</head>
<body>

<h1>Bouncing Ball Playground</h1>
<canvas id="sim" width="600" height="450"></canvas>
<div class="controls">
  <button id="drop">Drop Ball</button>
  <button id="play">Pause</button>
  <button id="clear">Clear All</button>
</div>
<p class="hint">Click anywhere on the canvas to add a ball at that position</p>

<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');

  // Canvas dimensions in pixels
  const w = canvas.width;
  const h = canvas.height;

  // Physics constants
  const GRAVITY = 600;        // pixels per second^2 (or per step at dt=1)
  const RESTITUTION = 0.85;   // energy loss on bounce (< 1)
  const FRICTION = 0.999;     // slight air resistance

  let balls = [];
  let running = true;

  // Color palette for balls
  const COLORS = [
    ['#e94560', '#c23152'],
    ['#f39c12', '#d68910'],
    ['#2ecc71', '#27ae60'],
    ['#3498db', '#2980b9'],
    ['#9b59b6', '#8e44ad'],
    ['#1abc9c', '#16a085'],
    ['#e74c3c', '#c0392b'],
    ['#f1c40f', '#d4ac0d'],
  ];

  function createBall(x, y, vx, vy, r) {
    const colorIdx = Math.floor(Math.random() * COLORS.length);
    return {
      x: x,
      y: y,
      vx: vx || 0,
      vy: vy || 0,
      r: r || (15 + Math.random() * 20), // radius between 15 and 35
      colorStart: COLORS[colorIdx][0],
      colorEnd: COLORS[colorIdx][1]
    };
  }

  function step(dt) {
    dt = dt || 1;

    for (let i = balls.length - 1; i >= 0; i--) {
      const b = balls[i];

      // Apply gravity
      b.vy += GRAVITY * dt;

      // Apply friction
      b.vx *= FRICTION;
      b.vy *= FRICTION;

      // Update position
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // Boundary checks with clamping and bounce
      // Floor
      if (b.y + b.r > h) {
        b.y = h - b.r;
        b.vy = -Math.abs(b.vy) * RESTITUTION;
        // Stop micro-bouncing when near rest
        if (Math.abs(b.vy) < 5) b.vy = 0;
      }

      // Ceiling
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = Math.abs(b.vy) * RESTITUTION;
      }

      // Right wall
      if (b.x + b.r > w) {
        b.x = w - b.r;
        b.vx = -Math.abs(b.vx) * RESTITUTION;
      }

      // Left wall
      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = Math.abs(b.vx) * RESTITUTION;
      }
    }

    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, w, h);

    // Draw subtle grid
    ctx.strokeStyle = 'rgba(69, 123, 157, 0.1)';
    ctx.lineWidth = 1;
    for (let x = 0; x < w; x += 50) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y < h; y += 50) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }

    // Draw each ball with a nice gradient
    for (const b of balls) {
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, lighten(b.colorStart, 40));
      grad.addColorStop(0.7, b.colorStart);
      grad.addColorStop(1, b.colorEnd);

      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Subtle glow
      ctx.shadowColor = b.colorStart;
      ctx.shadowBlur = 15;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    requestAnimationFrame(function() {
      if (running) step(1);
    });
  }

  function lighten(hex, percent) {
    const num = parseInt(hex.replace('#', ''), 16);
    const r = Math.min(255, (num >> 16) + percent);
    const g = Math.min(255, ((num >> 8) & 0x00FF) + percent);
    const b = Math.min(255, (num & 0x0000FF) + percent);
    return `rgb(${r},${g},${b})`;
  }

  // Public API
  window.sim = {
    w: w,
    h: h,

    balls: function() {
      return balls.map(function(b) {
        return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r };
      });
    },

    addBall: function(x, y, vx, vy, r) {
      // Default parameters handling
      if (typeof r === 'undefined') r = 15 + Math.random() * 20;
      if (typeof vy === 'undefined' && typeof vx !== 'undefined') vy = 0;
      if (typeof vy === 'undefined') vy = 0;

      balls.push(createBall(x, y, vx || 0, vy || 0, r));
    },

    clear: function() {
      balls = [];
    },

    step: function(dt) {
      dt = dt || 1;
      for (let d = 0; d < dt; d++) {
        // Apply gravity
        for (const b of balls) {
          b.vy += GRAVITY * dt;
          b.vx *= FRICTION;
          b.vy *= FRICTION;
          b.x += b.vx * dt;
          b.y += b.vy * dt;

          // Floor
          if (b.y + b.r > h) {
            b.y = h - b.r;
            b.vy = -Math.abs(b.vy) * RESTITUTION;
            if (Math.abs(b.vy) < 5) b.vy = 0;
          }

          // Ceiling
          if (b.y - b.r < 0) {
            b.y = b.r;
            b.vy = Math.abs(b.vy) * RESTITUTION;
          }

          // Right wall
          if (b.x + b.r > w) {
            b.x = w - b.r;
            b.vx = -Math.abs(b.vx) * RESTITUTION;
          }

          // Left wall
          if (b.x - b.r < 0) {
            b.x = b.r;
            b.vx = Math.abs(b.vx) * RESTITUTION;
          }
        }
      }
      draw();
    }
  };

  // Button handlers
  document.getElementById('drop').addEventListener('click', function() {
    const x = w / 2 + (Math.random() - 0.5) * 100;
    window.sim.addBall(x, 30, (Math.random() - 0.5) * 100, 0);
  });

  document.getElementById('play').addEventListener('click', function() {
    running = !running;
    const btn = document.getElementById('play');
    if (running) {
      btn.textContent = 'Pause';
      draw(); // restart animation loop
    } else {
      btn.textContent = 'Play';
    }
  });

  document.getElementById('clear').addEventListener('click', function() {
    window.sim.clear();
    ctx.clearRect(0, 0, w, h);
  });

  canvas.addEventListener('click', function(e) {
    const rect = canvas.getBoundingClientRect();
    // Scale for CSS size vs pixel size
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    window.sim.addBall(x, y);
  });

  // Start the simulation loop
  draw();
})();
</script>

</body>
</html>
